def pack(payload):
    items = payload["items"]
    capacity = payload["capacity"]
    n = len(items)

    # Step 1: Best-Fit Decreasing (BFD) baseline
    indexed_items = sorted(enumerate(items), key=lambda x: -x[1])
    bins = []  # list of [total_size, list_of_indices]

    for idx, size in indexed_items:
        best_bin_idx = -1
        min_remaining = capacity + 1

        for i, (total, _) in enumerate(bins):
            remaining = capacity - (total + size)
            if remaining >= 0 and remaining < min_remaining:
                min_remaining = remaining
                best_bin_idx = i

        if best_bin_idx != -1:
            bins[best_bin_idx][0] += size
            bins[best_bin_idx][1].append(idx)
        else:
            bins.append([size, [idx]])

    # Step 2: Local refinement — try to merge bins or improve packing
    improved = True
    while improved:
        improved = False
        # Try merging pairs of bins
        for i in range(len(bins) - 1, 0, -1):
            for j in range(i):
                # Check if bins i and j can be merged into one bin
                total_size = bins[i][0] + bins[j][0]
                if total_size <= capacity:
                    # Merge: combine items and use BFD on the union
                    merged_items = [(bins[i][1][k], items[bins[i][1][k]]) for k in range(len(bins[i][1]))]
                    merged_items += [(bins[j][1][k], items[bins[j][1][k]]) for k in range(len(bins[j][1]))
